    if (!clients.delete(c)) return;
    const wasHost = [...room][0] === c;
    room.delete(c);
    others({ type: 'leave', id: c.id });
    if (wasHost && room.size) { const h = [...room][0].id; for (const o of room) o.send({ type: 'host', id: h }); }
